// Generated by ml/train.py (--level 1|2|4|static) and ml/train_sequences.py (movement),
// outside git like the data they come from: run them before bundling the app.
import level1 from '../../../ml/languages/aed/models/level-1/model.json';
import level2 from '../../../ml/languages/aed/models/level-2/model.json';
import level4 from '../../../ml/languages/aed/models/level-4/model.json';
import movement from '../../../ml/languages/aed/models/movement/model.json';
import allStatic from '../../../ml/languages/aed/models/static/model.json';

import {
  handLocation,
  LOCATION_VERSION,
  normalizeHand,
  TWO_HANDS_VERSION,
} from '@/dataset/features';
import type { RecordedHand } from '@/dataset/types';

import { Classifier, type ModelFile, type Prediction } from './classifier';
import { type MovementModelFile, MovementRecognizer } from './sequences';

/** `static`: one model for every static one-handed letter (levels 1 and 2). */
export type ClassifierName = 'static' | 1 | 2 | 4;

const files: Record<ClassifierName, ModelFile> = {
  static: allStatic as ModelFile,
  1: level1 as ModelFile,
  2: level2 as ModelFile,
  4: level4 as ModelFile,
};
const cache = new Map<ClassifierName, Classifier>();

export function classifierFor(name: ClassifierName): Classifier {
  let classifier = cache.get(name);
  if (classifier == null) {
    const file = files[name];
    const { location, twoHands } = file.normalization;
    if (location != null && location.version !== LOCATION_VERSION) {
      throw new Error(
        `Model ${name} uses location v${location.version}, the app v${LOCATION_VERSION}. Retrain it.`,
      );
    }
    if (twoHands != null && twoHands.version !== TWO_HANDS_VERSION) {
      throw new Error(
        `Model ${name} uses two hands v${twoHands.version}, the app v${TWO_HANDS_VERSION}. Retrain it.`,
      );
    }
    classifier = new Classifier(file);
    cache.set(name, classifier);
  }
  return classifier;
}

let movementRecognizer: MovementRecognizer | null = null;

/** DTW templates for the movement letters (level 3). */
export function movementRecognizerFor(): MovementRecognizer {
  movementRecognizer ??= new MovementRecognizer(movement as MovementModelFile);
  return movementRecognizer;
}

/**
 * Prepares one hand exactly like training did (ADR 0008) and classifies it. The
 * hand MediaPipe reports is used as the dominant hand: left hands are mirrored.
 * Null if the input can't be built (e.g. the model needs the face and there's none).
 */
export function classifyHand(
  classifier: Classifier,
  hand: RecordedHand,
  body: number[],
  imageWidth: number,
  imageHeight: number,
): Prediction | null {
  const shape = normalizeHand(hand.world, hand.handedness);
  if (shape == null) {
    return null;
  }
  let input = shape;
  if (classifier.usesLocation) {
    const location = handLocation(hand.landmarks, body, imageWidth, imageHeight, hand.handedness);
    if (location == null) {
      return null;
    }
    input = [...shape, ...location];
  }
  return classifier.predict(input);
}
